// Isolation test (OS-12) — construct AuthorizationForms with its declared inputs and nothing else, then
// exercise every public operation. (Generated by new-object.py, rewritten for strict TypeScript - MF-21.)
import { describe, expect, it } from "vitest";
import { asProjection, height, uncomputable } from "../src/kernel/index.js";
import { AuthorizationForms, type RatioSource } from "../src/spend/index.js";
import { c0, c1, u } from "./support/spend-parts.js";

const ratioOf = (a: number): RatioSource => ({ of: (unit) => asProjection("Ratio", () => ({ unit, counts: [{ currency: c0, count: a }, { currency: c1, count: 0 }] })) });
const at = height(1);

describe("AuthorizationForms in isolation", () => {
  it("refuses to construct when an input is missing", () => {
    expect(() => new AuthorizationForms({} as never)).toThrow();
  });

  it("refuses inputs that do not offer the operations it calls (OS-1, declared slots)", () => {
    expect(() => new AuthorizationForms({ ratio: {} as never })).toThrow();
  });

  it("build answers differently when ratio differs", () => {
    expect(new AuthorizationForms({ ratio: ratioOf(1) }).build(u, c1, at)).not.toEqual(new AuthorizationForms({ ratio: ratioOf(4) }).build(u, c1, at));
    const broken: RatioSource = { of: () => asProjection("Ratio", () => uncomputable("x")) };
    expect(new AuthorizationForms({ ratio: broken }).build(u, c1, at), "a form was built without its ratio").toEqual(uncomputable("x"));
  });
});
